+
+static bool s_th_dbg_enabled = (TH_DEBUG_MODE_ENABLE != 0);
+static uint32_t s_last_th_state_log_ms = 0U;
+static bool s_th_state_log_init = false;
+static th_dbg_rx_parser_t s_dbg_rx;
+static th_dbg_state_t s_th_dbg_state = {
+    0, 0, 0U, 0U, 0U, 0U, 0U, 0U, 0U, "NONE", "IDLE"
+};
