+static void th_dbg_sync_runtime_state(void)
+{
+  minimc_temp_report_payload_t report;
+  if (thermistor_adc_get_telemetry(&report))
+  {
+    s_th_dbg_state.nozzle_ddC = report.current_temp_deci_c;
+    s_th_dbg_state.adc_raw = report.raw_adc_value;
+    s_th_dbg_state.fault = report.sensor_status;
+    const bool high_temp_range = ((report.raw_adc_value > 0U) && (report.raw_adc_value < 1000U));
+    s_th_dbg_state.pullup_sel = (report.reserved != 0U)
+                                    ? (uint8_t)(report.reserved & 0x01U)
+                                    : (high_temp_range ? 1U : 0U);
+  }
+  s_th_dbg_state.filament_mask = (Board_getFilamentStatus() == 0U) ? 0x0FU : 0x00U;
+  s_th_dbg_state.active_slot = (uint8_t)(active_extruder & 0x03U);
+  s_th_dbg_state.slot = s_th_dbg_state.active_slot;
+  if (load_filament_Flag == 1)
+  {
+    s_th_dbg_state.op_str = "LOAD";
+    s_th_dbg_state.step_str = "FEEDING";
+  }
+  else if (load_filament_Flag == 2)
+  {
+    s_th_dbg_state.op_str = "UNLOAD";
+    s_th_dbg_state.step_str = "RETRACTING";
+  }
+}
+
+static void th_dbg_rx_reset(void)
+{
+  s_dbg_rx.idx = 0U;
+  s_dbg_rx.expected_len = 0U;
+  s_dbg_rx.state = TH_DBG_PARSE_IDLE;
+}
