+static const char *th_dbg_node_name(uint8_t node_id)
+{
+  if (node_id == MINIMC_NODE_MC)
+  {
+    return "MC";
+  }
+  return "TH";
+}
+
+void th_debug_set_enabled(bool enabled)
+{
+  s_th_dbg_enabled = enabled;
+}
+
+bool th_debug_is_enabled(void)
+{
+  return s_th_dbg_enabled;
+}
