+uint32_t USART3_get_tx_drop_count(void)
+{
+  return usart3_tx_drop_count;
+}
+
+uint32_t USART3_get_tx_trunc_count(void)
+{
+  return usart3_tx_trunc_count;
+}
+
+static uint16_t usart3_tx_free_space(void)
+{
+  const uint16_t head = usart3_tx_head;
+  const uint16_t tail = usart3_tx_tail;
+  if (head >= tail)
+  {
+    return (uint16_t)((USART3_TXBUFF_SIZE - 1U) - (head - tail));
+  }
+  return (uint16_t)((tail - head) - 1U);
+}
+
+bool th_debug_write(const char *buf, uint16_t len)
+{
+  if ((buf == NULL) || (len == 0U) || (!s_th_dbg_enabled))
+  {
+    return false;
+  }
+  const bool is_truncated = (len > TH_DBG_LINE_MAX_LEN);
+  const uint16_t req_len = is_truncated ? TH_DBG_LINE_MAX_LEN : len;
+  if (usart3_tx_free_space() < req_len)
+  {
+    usart3_tx_drop_count++;
+    return false;
+  }
+  if (!is_truncated)
+  {
+    return (USART3_write((const uint8_t *)buf, len) == (int)len);
+  }
+  char trunc_buf[TH_DBG_LINE_MAX_LEN];
+  memcpy(trunc_buf, buf, TH_DBG_LINE_MAX_LEN - 5U);
+  memcpy(&trunc_buf[TH_DBG_LINE_MAX_LEN - 5U], "...\r\n", 5U);
+  usart3_tx_trunc_count++;
+  return (USART3_write((const uint8_t *)trunc_buf, TH_DBG_LINE_MAX_LEN) == (int)TH_DBG_LINE_MAX_LEN);
+}
+
+static void th_dbg_emit(const th_dbg_meta_t *meta, const char *kv_str)
+{
+  if ((meta == NULL) || (!s_th_dbg_enabled))
+  {
+    return;
+  }
+  char line_buf[256];
+  const uint32_t ts_ms = get_tick_count();
+  const char *extra = (kv_str != NULL) ? kv_str : "";
+  const char *sep = (extra[0] != '\0') ? " " : "";
+  const int n = snprintf(
+      line_buf,
+      sizeof(line_buf),
+      "[TH-DBG] ts=%lu dir=%s node=%s seq=%u cmd=0x%02X status=%s %s%sdrop=%lu trunc=%lu\r\n",
+      (unsigned long)ts_ms,
+      meta->dir,
+      meta->node,
+      (unsigned int)meta->seq,
+      (unsigned int)meta->cmd,
+      meta->status,
+      extra,
+      sep,
+      (unsigned long)usart3_tx_drop_count,
+      (unsigned long)usart3_tx_trunc_count);
+  if (n > 0)
+  {
+    (void)th_debug_write(line_buf, (uint16_t)n);
+  }
+}
