+static void th_dbg_format_temp_kv(char *out_kv, size_t cap)
+{
+  if ((out_kv == NULL) || (cap == 0U))
+  {
+    return;
+  }
+  (void)snprintf(
+      out_kv,
+      cap,
+      "nozzle_ddC=%d adc_raw=%u pullup_sel=%u fault=%u",
+      (int)s_th_dbg_state.nozzle_ddC,
+      (unsigned int)s_th_dbg_state.adc_raw,
+      (unsigned int)s_th_dbg_state.pullup_sel,
+      (unsigned int)s_th_dbg_state.fault);
+}
+
+static void th_dbg_format_filament_kv(char *out_kv, size_t cap)
+{
+  if ((out_kv == NULL) || (cap == 0U))
+  {
+    return;
+  }
+  (void)snprintf(
+      out_kv,
+      cap,
+      "op=%s slot=%u active_slot=%u filament_present_mask=0x%02X step_state=%s",
+      s_th_dbg_state.op_str,
+      (unsigned int)s_th_dbg_state.slot,
+      (unsigned int)s_th_dbg_state.active_slot,
+      (unsigned int)s_th_dbg_state.filament_mask,
+      s_th_dbg_state.step_str);
+}
+
+static void th_dbg_log_frame_err(const uint8_t *hdr, const char *status_str, uint8_t err_code)
+{
+  if ((hdr == NULL) || (status_str == NULL))
+  {
+    return;
+  }
+  char kv[32];
+  (void)snprintf(kv, sizeof(kv), "err_code=0x%02X", (unsigned int)err_code);
+  const uint8_t node_id = ((hdr[4] & MINIMC_FLAG_IS_RESPONSE) != 0U) ? hdr[2] : hdr[3];
+  const th_dbg_meta_t meta = {
+      "ERR",
+      th_dbg_node_name(node_id),
+      hdr[8],
+      hdr[5],
+      status_str
+  };
+  th_dbg_emit(&meta, kv);
+}
+
+void th_debug_notify_filament(const char *op, uint8_t slot, uint8_t present_mask, const char *step_state)
+{
+  if ((op == NULL) || (step_state == NULL))
+  {
+    return;
+  }
+  const uint8_t norm_slot = (uint8_t)(slot & 0x03U);
+  active_extruder = norm_slot;
+  s_th_dbg_state.slot = norm_slot;
+  s_th_dbg_state.active_slot = norm_slot;
+  s_th_dbg_state.filament_mask = present_mask;
+  s_th_dbg_state.op_str = op;
+  s_th_dbg_state.step_str = step_state;
+  char state_kv[128];
+  th_dbg_format_filament_kv(state_kv, sizeof(state_kv));
+  const uint8_t cmd_id = (strcmp(op, "SELECT") == 0) ? MINIMC_CMD_SLOT_SELECT : MINIMC_CMD_FILAMENT_CONTROL;
+  const th_dbg_meta_t st_meta = { "STATE", "TH", s_th_dbg_state.last_seq, cmd_id, "OK" };
+  th_dbg_emit(&st_meta, state_kv);
+}
+
+static void th_dbg_handle_valid_rx_frame(const uint8_t *frame, uint16_t len)
+{
+  if ((frame == NULL) || (len < MINIMC_HEADER_SIZE))
+  {
+    return;
+  }
+  const uint8_t dst_id = frame[3];
+  const uint8_t flags = frame[4];
+  const bool valid_dst = ((dst_id == MINIMC_NODE_TH) || (dst_id == MINIMC_NODE_BROADCAST));
+  if (((flags & MINIMC_FLAG_PROTO_V2) == 0U) || ((flags & MINIMC_FLAG_IS_RESPONSE) != 0U) || (!valid_dst))
+  {
+    th_dbg_log_frame_err(frame, "BAD_FRAME", 0x02U);
+    return;
+  }
+  const uint8_t cmd_id = frame[5];
+  const uint8_t seq_u8 = frame[8];
+  const uint16_t plen = (uint16_t)frame[10] | (uint16_t)((uint16_t)frame[11] << 8U);
+  s_th_dbg_state.last_seq = seq_u8;
+
+  char rx_kv[96];
+  if ((cmd_id == MINIMC_CMD_SET_TEMP) && (plen >= 2U))
+  {
+    const int16_t n_set = (int16_t)((uint16_t)frame[12] | ((uint16_t)frame[13] << 8U));
+    (void)snprintf(rx_kv, sizeof(rx_kv), "len=%u nozzle_set=%d", (unsigned int)len, (int)n_set);
+  }
+  else if ((cmd_id == MINIMC_CMD_FILAMENT_CONTROL) || (cmd_id == MINIMC_CMD_SLOT_SELECT))
+  {
+    const uint8_t slot = (plen > 0U) ? (uint8_t)(frame[12] & 0x03U) : 0U;
+    const bool is_unload = ((cmd_id == MINIMC_CMD_FILAMENT_CONTROL) && (plen > 1U) && (frame[13] == 1U));
+    const char *op_s = (cmd_id == MINIMC_CMD_SLOT_SELECT) ? "SELECT" : (is_unload ? "UNLOAD" : "LOAD");
+    (void)snprintf(rx_kv, sizeof(rx_kv), "len=%u op=%s slot=%u", (unsigned int)len, op_s, (unsigned int)slot);
+  }
+  else
+  {
+    (void)snprintf(rx_kv, sizeof(rx_kv), "len=%u", (unsigned int)len);
+  }
+
+  const th_dbg_meta_t rx_meta = { "RX", th_dbg_node_name(dst_id), seq_u8, cmd_id, "OK" };
+  th_dbg_emit(&rx_meta, rx_kv);
+}
+
+static bool th_dbg_rx_step_sof(uint8_t byte)
+{
+  if (s_dbg_rx.state == TH_DBG_PARSE_IDLE)
+  {
+    if (byte == MINIMC_SOF_1)
+    {
+      s_dbg_rx.buf[0] = byte;
+      s_dbg_rx.idx = 1U;
+      s_dbg_rx.state = TH_DBG_PARSE_SOF2;
+    }
+    return true;
+  }
+  if (s_dbg_rx.state == TH_DBG_PARSE_SOF2)
+  {
+    if (byte == MINIMC_SOF_2)
+    {
+      s_dbg_rx.buf[1] = byte;
+      s_dbg_rx.idx = 2U;
+      s_dbg_rx.state = TH_DBG_PARSE_HEADER;
+    }
+    else if (byte != MINIMC_SOF_1)
+    {
+      th_dbg_rx_reset();
+    }
+    return true;
+  }
+  return false;
+}
+
+static void th_dbg_finish_rx_crc(void)
+{
+  const uint16_t body_len = (uint16_t)(s_dbg_rx.expected_len - MINIMC_CRC_SIZE);
+  const uint16_t calc_c = minimc_crc16(s_dbg_rx.buf, body_len);
+  const uint16_t rx_c = (uint16_t)s_dbg_rx.buf[body_len] |
+                        (uint16_t)((uint16_t)s_dbg_rx.buf[body_len + 1U] << 8U);
+  if (calc_c == rx_c)
+  {
+    th_dbg_handle_valid_rx_frame(s_dbg_rx.buf, s_dbg_rx.expected_len);
+  }
+  else
+  {
+    th_dbg_log_frame_err(s_dbg_rx.buf, "CRC_ERR", 0x01U);
+  }
+  th_dbg_rx_reset();
+}
+
+static void th_dbg_observe_rx_byte(uint8_t byte)
+{
+  const uint32_t now_ms = get_tick_count();
+  if ((s_dbg_rx.state != TH_DBG_PARSE_IDLE) &&
+      ((uint32_t)(now_ms - s_dbg_rx.last_byte_ms) > TH_DBG_PARSE_TIMEOUT_MS))
+  {
+    th_dbg_rx_reset();
+  }
+  s_dbg_rx.last_byte_ms = now_ms;
+  if (th_dbg_rx_step_sof(byte))
+  {
+    return;
+  }
+  s_dbg_rx.buf[s_dbg_rx.idx] = byte;
+  s_dbg_rx.idx++;
+
+  if ((s_dbg_rx.state == TH_DBG_PARSE_HEADER) && (s_dbg_rx.idx == MINIMC_HEADER_SIZE))
+  {
+    const uint16_t plen = (uint16_t)s_dbg_rx.buf[10] | (uint16_t)((uint16_t)s_dbg_rx.buf[11] << 8U);
+    if (plen > MINIMC_MAX_PAYLOAD_SIZE)
+    {
+      th_dbg_log_frame_err(s_dbg_rx.buf, "BAD_FRAME", 0x02U);
+      th_dbg_rx_reset();
+      return;
+    }
+    s_dbg_rx.expected_len = (uint16_t)(MINIMC_HEADER_SIZE + plen + MINIMC_CRC_SIZE);
+    s_dbg_rx.state = (plen == 0U) ? TH_DBG_PARSE_CRC : TH_DBG_PARSE_PAYLOAD;
+  }
+  else if ((s_dbg_rx.state == TH_DBG_PARSE_PAYLOAD) &&
+           (s_dbg_rx.idx == (uint16_t)(s_dbg_rx.expected_len - MINIMC_CRC_SIZE)))
+  {
+    s_dbg_rx.state = TH_DBG_PARSE_CRC;
+  }
+  else if ((s_dbg_rx.state == TH_DBG_PARSE_CRC) && (s_dbg_rx.idx >= s_dbg_rx.expected_len))
+  {
+    th_dbg_finish_rx_crc();
+  }
+}
+
+static void th_dbg_log_tx_temp_report(const uint8_t *data, uint8_t seq_u8, uint8_t cmd_id)
+{
+  char kv[128];
+  s_th_dbg_state.nozzle_ddC = (int16_t)((uint16_t)data[12] | ((uint16_t)data[13] << 8U));
+  s_th_dbg_state.adc_raw = (uint16_t)data[16] | (uint16_t)((uint16_t)data[17] << 8U);
+  s_th_dbg_state.fault = data[18];
+  const bool high_temp_range = ((s_th_dbg_state.adc_raw > 0U) && (s_th_dbg_state.adc_raw < 1000U));
+  s_th_dbg_state.pullup_sel = (data[24] != 0U) ? (uint8_t)(data[24] & 0x01U) : (high_temp_range ? 1U : 0U);
+  th_dbg_format_temp_kv(kv, sizeof(kv));
+  const th_dbg_meta_t st_meta = { "STATE", "TH", seq_u8, cmd_id, "OK" };
+  const th_dbg_meta_t tx_meta = { "TX", "TH", seq_u8, cmd_id, "ACK" };
+  th_dbg_emit(&st_meta, kv);
+  th_dbg_emit(&tx_meta, kv);
+}
+
+static void th_dbg_observe_tx_frame(const uint8_t *data, uint16_t len)
+{
+  if ((data == NULL) || (len < MINIMC_HEADER_SIZE))
+  {
+    return;
+  }
+  if ((data[0] != MINIMC_SOF_1) || (data[1] != MINIMC_SOF_2))
+  {
+    return;
+  }
+  const uint8_t cmd_id = data[5];
+  const uint8_t seq_u8 = data[8];
+  const uint16_t plen = (uint16_t)data[10] | (uint16_t)((uint16_t)data[11] << 8U);
+  s_th_dbg_state.last_seq = seq_u8;
+  char kv[96];
+
+  if ((cmd_id == MINIMC_CMD_TEMP_REPORT) && (len >= 28U))
+  {
+    th_dbg_log_tx_temp_report(data, seq_u8, cmd_id);
+    return;
+  }
+  if ((cmd_id == MINIMC_CMD_VERSION_REPORT) && (len >= 16U))
+  {
+    (void)snprintf(kv, sizeof(kv), "fw=%u.%u", (unsigned int)data[14], (unsigned int)data[15]);
+    const th_dbg_meta_t tx_meta = { "TX", "TH", seq_u8, cmd_id, "ACK" };
+    th_dbg_emit(&tx_meta, kv);
+    return;
+  }
+  if (cmd_id == MINIMC_CMD_PONG)
+  {
+    const th_dbg_meta_t tx_meta = { "TX", "TH", seq_u8, cmd_id, "ACK" };
+    th_dbg_emit(&tx_meta, "pong=1");
+    return;
+  }
+  if (cmd_id == MINIMC_CMD_NACK)
+  {
+    const uint8_t err_code = (plen >= 1U) ? data[12] : 0x04U;
+    (void)snprintf(kv, sizeof(kv), "err_code=0x%02X", (unsigned int)err_code);
+    const th_dbg_meta_t err_meta = { "ERR", "TH", seq_u8, cmd_id, "BAD_FRAME" };
+    const th_dbg_meta_t tx_meta = { "TX", "TH", seq_u8, cmd_id, "NACK" };
+    th_dbg_emit(&err_meta, kv);
+    th_dbg_emit(&tx_meta, kv);
+    return;
+  }
+  (void)snprintf(kv, sizeof(kv), "len=%u", (unsigned int)len);
+  const th_dbg_meta_t tx_meta = { "TX", "TH", seq_u8, cmd_id, "ACK" };
+  th_dbg_emit(&tx_meta, kv);
+}
+
+void th_debug_log_periodic_state(uint32_t now_ms)
+{
+  if (!s_th_dbg_enabled)
+  {
+    return;
+  }
+  if (s_th_state_log_init && ((uint32_t)(now_ms - s_last_th_state_log_ms) < TH_DBG_STATE_INTERVAL_MS))
+  {
+    return;
+  }
+  s_last_th_state_log_ms = now_ms;
+  s_th_state_log_init = true;
+  th_dbg_sync_runtime_state();
+
+  char kv[128];
+  th_dbg_format_temp_kv(kv, sizeof(kv));
+  const th_dbg_meta_t temp_meta = { "STATE", "TH", s_th_dbg_state.last_seq, MINIMC_CMD_GET_TEMP, "OK" };
+  th_dbg_emit(&temp_meta, kv);
+
+  th_dbg_format_filament_kv(kv, sizeof(kv));
+  const th_dbg_meta_t fil_meta = { "STATE", "TH", s_th_dbg_state.last_seq, MINIMC_CMD_FILAMENT_CONTROL, "OK" };
+  th_dbg_emit(&fil_meta, kv);
+}

