+static void test_negative_crc_err_bad_frame_and_recovery(void)
+{
+    clear_capture();
+
+    /* 1. Invalid len=0 or oversized len=100 to usart1_send_raw -> no DMA TX, no false ACK */
+    uint8_t oversize_frame[100];
+    memset(oversize_frame, 0, sizeof(oversize_frame));
+    oversize_frame[0] = MINIMC_SOF_1;
+    oversize_frame[1] = MINIMC_SOF_2;
+    oversize_frame[2] = MINIMC_NODE_TH;
+    oversize_frame[3] = MINIMC_NODE_MC;
+    oversize_frame[4] = (uint8_t)(MINIMC_FLAG_IS_RESPONSE | MINIMC_FLAG_PROTO_V2);
+    oversize_frame[5] = MINIMC_CMD_TEMP_REPORT;
+    oversize_frame[8] = 13U;
+    usart1_send_raw(NULL, 14U);
+    usart1_send_raw(oversize_frame, 0U);
+    assert(s_usart1_last_tx_len == 0U);
+    assert(s_usart3_capture_len == 0U);
+    usart1_send_raw(oversize_frame, 100U);
+    drain_usart3_dma();
+    assert(s_usart1_last_tx_len == 0U);
+    assert(strstr(s_usart3_capture, "dir=TX") == NULL);
+    assert(strstr(s_usart3_capture, "dir=ERR node=TH seq=13 cmd=0x14 status=TX_ERR err_code=0x06") != NULL);
+
+    /* 2. Simulate USART1 DMA TX failure on ACK and NACK paths -> logs TX_ERR, no false TX log */
+    clear_capture();
+    s_usart1_tx_fail = true;
+    inject_minimc_req(14U, MINIMC_CMD_GET_TEMP, NULL, 0U);
+    const uint8_t set_pay[2] = { 0x00U, 0x08U };
+    inject_minimc_req(15U, MINIMC_CMD_SET_TEMP, set_pay, 2U);
+    assert(s_usart1_last_tx_len == 0U);
+    assert(strstr(s_usart3_capture, "dir=TX") == NULL);
+    assert(strstr(s_usart3_capture, "dir=ERR node=TH seq=14 cmd=0x14 status=TX_ERR err_code=0x06") != NULL);
+    assert(strstr(s_usart3_capture, "dir=ERR node=TH seq=15 cmd=0x06 status=TX_ERR err_code=0x06") != NULL);
